package mathx

// Clamp returns v restricted to the inclusive range [lo, hi].
// It assumes lo <= hi.
func Clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

